    d = {"id": id, "kind": kind, "name": name}
    if native: d["native_name"] = native
    if where: d["where"] = {"label": where[0], "lat": where[1], "lon": where[2]}
    if when: d["when"] = when
    d.update({"image_ids": imgs, "media_ids": media or [], "spot_it": spot_it, "story_md": story,
              "why_it_matters": why, "memory_hook": hook, "source_ids": srcs})
    if compare: d["compare"] = compare
    return d

